import json

# Parse each variable, stripping the trailing (.venv) prompt
flight_data = json.loads(flight_out.split("\n(.venv)")[0].strip())["result"]
hotel_data = json.loads(hotel_out.split("\n(.venv)")[0].strip())["result"]
car_data = json.loads(car_out.split("\n(.venv)")[0].strip())["result"]

# Flight details
cabin = flight_data["cabin_class"]
route_type = flight_data["route_type"]
price_paid = flight_data["price_paid"]
has_insurance = flight_data["add_insurance"]

# Compute flight cancellation fee per policy
if has_insurance:
    flight_fee = 0
elif cabin == "first":
    flight_fee = 0
elif cabin == "business":
    if route_type == "domestic":
        flight_fee = round(price_paid * 0.05, 2)
    else:
        flight_fee = round(price_paid * 0.08, 2)
elif cabin == "economy":
    if route_type == "domestic":
        flight_fee = max(50, round(price_paid * 0.15, 2))
    else:
        flight_fee = max(75, round(price_paid * 0.20, 2))
else:
    flight_fee = price_paid  # basic_economy non-cancellable

flight_refund = price_paid - flight_fee

# Hotel: Standard King, check-in 2026-09-18, today 2026-06-15 = 95 days away (>48h)
nightly_rate = hotel_data["nightly_rate"]
hotel_total = hotel_data["total_price"]
room_type = hotel_data["room_type"]
is_suite = "suite" in room_type.lower()

if is_suite:
    hotel_fee = hotel_total
else:
    hotel_fee = 0  # 95 days > 48h → free cancellation
hotel_refund = hotel_total - hotel_fee

# Car: Economy, pickup 2026-09-18, today 2026-06-15 = 95 days away (>24h)
car_total = car_data["total_price"]
daily_rate = car_data["daily_rate"]
car_class = car_data["car_class"]
is_luxury_suv = car_class.lower() in ["luxury", "suv"]

car_fee = 0  # 95 days > 24h → free cancellation
